        '    float can = abs(sdRound(q + vec2(s * 0.12, -s * 0.06), vec2(s * 0.26, s * 0.16), s * 0.04)) - 0.9;',
        '    float cap = abs(sdBox(q + vec2(s * 0.12, s * 0.16), vec2(s * 0.07, s * 0.04))) - 0.8;',
        '    float spout = abs(sdSegment(q, vec2(s * 0.14, -s * 0.02), vec2(s * 0.44, -s * 0.16), 0.0)) - 0.9;',
